// Script to parse .env.test and POST the variables to the documentation endpoint

const fs = require('fs');
const path = require('path');
const https = require('https');

// Read the .env.test file
const envPath = path.join(__dirname, '.env.test');
const envContent = fs.readFileSync(envPath, 'utf8');

// Parse environment variables into an object
const envVars = {};
const lines = envContent.split('\n');

lines.forEach(line => {
  const trimmedLine = line.trim();
  if (trimmedLine && !trimmedLine.startsWith('#')) {
    const [key, value] = trimmedLine.split('=');
    if (key && value) {
      envVars[key] = value;
    }
  }
});

// Prepare the JSON payload
const jsonPayload = JSON.stringify(envVars);

// POST request options
const options = {
  hostname: 'localhost',
  port: 47301,
  path: '/api/doc-export',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(jsonPayload)
  }
};

// Make the POST request
const req = https.request(options, (res) => {
  console.log(`Status Code: ${res.statusCode}`);
  console.log('Environment variables posted successfully.');

  res.on('data', (chunk) => {
    console.log(`Response: ${chunk}`);
  });
});

req.on('error', (error) => {
  console.error(`Error posting environment variables: ${error.message}`);
});

req.write(jsonPayload);
req.end();

