### Steps:
1. Write a script (e.g., in Node.js) to read the `.env.test` file.
2. Parse the environment variables into a JSON object.
3. Send a POST request to `http://localhost:47301/api/doc-export` with the JSON payload.

### Example Script:
Here’s a Node.js script to accomplish this:

```javascript
const fs = require('fs');
const axios = require('axios');

const envFilePath = '.env.test';
const targetUrl = 'http://localhost:47301/api/doc-export';

fs.readFile(envFilePath, 'utf8', (err, data) => {
  if (err) {
    console.error('Error reading .env.test:', err);
    return;
  }

  const envVariables = {};
  const lines = data.split('\n');

  lines.forEach(line => {
    line = line.trim();
    if (line && !line.startsWith('#')) {
      const [key, value] = line.split('=');
      if (key && value) {
        envVariables[key.trim()] = value.trim();
      }
    }
  });

  axios.post(targetUrl, envVariables)
    .then(response => {
      console.log('Success:', response.data);
    })
    .catch(error => {
      console.error('Error posting to target URL:', error.message);
    });
});
```

### Instructions:
1. Save the script above to a file (e.g., `post_env.js`).
2. Ensure you have the required dependencies (`axios`, `node.js`).
3. Run the script using Node.js:
   ```bash
   node post_env.js
